 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sr, sc = next((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2)
    if sr == 0:
        dr, dc = 1, 0
    elif sr == h - 1:
        dr, dc = -1, 0
    elif sc == 0:
        dr, dc = 0, 1
    else:
        dr, dc = 0, -1

    todo = deque([(sr, sc, dr, dc)])
    seen = set()
    while todo:
        r, c, dr, dc = todo.popleft()
        state = (r, c, dr, dc)
        if state in seen:
            continue
        seen.add(state)
        while True:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < h and 0 <= nc < w):
                break
            if grid[nr][nc] != 8:
                r, c = nr, nc
                if out[r][c] == 0:
                    out[r][c] = 2
                continue

            # A ray meeting a wall follows the wall's near face in both
            # transverse directions, to the first opening (or canvas edge).
            pr, pc = r, c
            tdr, tdc = (0, 1) if dr else (1, 0)
            for sign in (-1, 1):
                rr, cc = pr, pc
                while True:
                    if out[rr][cc] == 0:
                        out[rr][cc] = 2
                    if grid[nr][nc] != 8:  # defensive; the hit location is a wall
                        break
                    if grid[nr][nc] != 8:
                        break
                    # The wall's corresponding cell is open: cross and resume.
                    wr, wc = nr + (rr - pr), nc + (cc - pc)
                    if not (0 <= wr < h and 0 <= wc < w):
                        break
                    if grid[wr][wc] != 8:
                        if out[wr][wc] == 0:
                            out[wr][wc] = 2
                        todo.append((wr, wc, dr, dc))
                        break
                    rr += sign * tdr
                    cc += sign * tdc
                    if not (0 <= rr < h and 0 <= cc < w):
                        break
            break
    return out
"
}

